const { body, validationResult } = require('express-validator');

// 使用 express-validator 进行数据验证
app.post('/api/users', [
    // 验证用户名
    body('username')
        .isLength({ min: 3, max: 30 })
        .withMessage('用户名长度必须在3到30个字符之间')
        .isAlphanumeric()
        .withMessage('用户名只能包含字母和数字'),

