#### 3.3.4 jsonwebtoken - JWT Authentication Mechanism
**Implementation Principle**: JWT (JSON Web Token) is a stateless authentication mechanism that transmits user identity information through encrypted JSON tokens.

**Design Approach**:
- Composed of three parts: Header, Payload, and Signature
- Uses a secret key for signing to ensure token integrity
- Stateless design reducing server storage pressure
- Supports expiration time and refresh mechanisms

**Practical Application**:
```javascript
const jwt = require('jsonwebtoken');

// Generate JWT token
function generateToken(user) {
    return jwt.sign(
        { userId: user._id, username: user.username },
        process.env.JWT_SECRET,
        { expiresIn: '24h' }
    );
}

// Middleware to verify JWT token
function verifyToken(req, res, next) {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
        return res.status(401).json({ message: 'No token provided' });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
        if (err) {
            return res.status(401).json({ message: 'Invalid token' });
        }

        req.user = decoded;
        next();
    });
}

// Use verification middleware to protect routes
app.get('/api/protected', verifyToken, (req, res) => {
    res.json({ message: 'Protected route accessed successfully', user: req.user });
});
```

#### 3.3.5 bcryptjs - Password Hashing
**Implementation Principle**: bcryptjs is a library for password hashing based on the Blowfish encryption algorithm, supporting automatic salt generation and adjustable work factors.

**Design Approach**:
- Automatically generates random salt to prevent rainbow table attacks
- Adjustable work factor controlling hash computation difficulty
- Supports async and sync hash computation
- Cross-language compatibility

**Practical Application**:
```javascript
const bcrypt = require('bcryptjs');

// Hash password
async function hashPassword(password) {
    const salt = await bcrypt.genSalt(12);
    return await bcrypt.hash(password, salt);
}

// Verify password
async function verifyPassword(password, hashedPassword) {
    return await bcrypt.compare(password, hashedPassword);
}

// User registration example
app.post('/api/register', async (req, res) => {
    try {
        const { username, email, password, name } = req.body;

        // Check if user already exists
        const existingUser = await User.findOne({ $or: [{ username }, { email }] });
        if (existingUser) {
            return res.status(400).json({ message: 'User already exists' });
        }

        // Hash password
        const passwordHash = await hashPassword(password);

        // Create new user
        const newUser = new User({
            username,
            email,
            passwordHash,
            name
        });

        await newUser.save();

        // Generate token
        const token = generateToken(newUser);

        res.status(201).json({ message: 'User registered successfully', token });
    } catch (error) {
        res.status(500).json({ message: 'Registration failed', error: error.message });
    }
});
```

