- Use Content-Security-Policy headers
- Avoid using innerHTML to directly insert untrusted content
- Use secure template engines

**Practical Application**:
```javascript
// HTML escape function
function escapeHtml(text) {
    if (!text) return '';
    return text
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// Safely insert user input
function insertUserContent(element, content) {
    element.textContent = content; // Safe, won't execute HTML
    // Avoid using element.innerHTML = content; // Unsafe, may lead to XSS
}

// Set Content-Security-Policy headers
app.use((req, res, next) => {
    res.setHeader(
        'Content-Security-Policy',
        "default-src 'self'; script-src 'self' https://cdn.example.com; style-src 'self' https://fonts.googleapis.com; img-src 'self' data:; font-src 'self' https://fonts.gstatic.com;"
    );
    next();
});
```

