// Local storage optimization manager
class OptimizedLocalStorage {
    constructor(storageKey = 'studyai_data', cacheSize = 100) {
        this.storageKey = storageKey;
        this.cacheSize = cacheSize;
        this.memoryCache = null;
        this.isDirty = false;

        // Auto-save at intervals (every 5 seconds)
        this.autoSaveInterval = setInterval(() => {
            if (this.isDirty) {
                this.saveData();
            }
        }, 5000);

        // Initialize cache
        this.loadData();
    }

    // Load data from local storage to memory cache
    loadData() {
        try {
            const storedData = localStorage.getItem(this.storageKey);
            this.memoryCache = storedData ? JSON.parse(storedData) : this.getDefaultData();
            this.isDirty = false;
        } catch (error) {
            console.error('Error loading data from localStorage:', error);
            this.memoryCache = this.getDefaultData();
            this.isDirty = true;
        }
    }

    // Get default data structure
