#### 3.3.3 Multer - ファイルアップロード処理
**実装原理**：Multerは `multipart/form-data` を処理するミドルウェアで、ファイルアップロードの処理に使用します。

**設計思想**：
- メモリストレージとディスクストレージをサポート
- ファイルフィルタリングと制限をサポート
- 複数ファイルアップロードをサポート
- ファイル名と保存パスのカスタマイズが可能

**実用例**：
```javascript
const multer = require('multer');

// ストレージエンジンの設定
const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, 'uploads/');
    },
    filename: function (req, file, cb) {
        cb(null, Date.now() + '-' + file.originalname);
    }
});

// ファイルフィルタの設定
const fileFilter = (req, file, cb) => {
    if (file.mimetype.startsWith('image/')) {
        cb(null, true);
    } else {
        cb(new Error('画像のみ許可されています！'), false);
    }
};

// multerインスタンスの作成
const upload = multer({
    storage: storage,
    limits: {
        fileSize: 1024 * 1024 * 5 // 5MB制限
    },
    fileFilter: fileFilter
});

// multerを使用して単一ファイルアップロードを処理
app.post('/api/upload', upload.single('image'), (req, res) => {
    res.json({ message: 'ファイルが正常にアップロードされました', file: req.file });
});
```

#### 3.3.4 jsonwebtoken - JWT認証メカニズム
**実装原理**：JWT（JSON Web Token）はステートレスな認証メカニズムで、暗号化されたJSONトークンを通じてユーザー身分情報を伝達します。

**設計思想**：
- Header、Payload、Signatureの3部分で構成
- 秘密鍵で署名し、トークンの整合性を確保
- ステートレス設計でサーバーストレージの負荷を軽減
- 有効期限とリフレッシュメカニズムをサポート

**実用例**：
```javascript
const jwt = require('jsonwebtoken');

// JWTトークン生成
function generateToken(user) {
    return jwt.sign(
        { userId: user._id, username: user.username },
        process.env.JWT_SECRET,
        { expiresIn: '24h' }
    );
}

// JWTトークン検証ミドルウェア
function verifyToken(req, res, next) {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
        return res.status(401).json({ message: 'トークンが提供されていません' });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
        if (err) {
            return res.status(401).json({ message: '無効なトークンです' });
        }

        req.user = decoded;
        next();
    });
}

// 検証ミドルウェアを使用してルートを保護
app.get('/api/protected', verifyToken, (req, res) => {
    res.json({ message: '保護されたルートに正常にアクセスしました', user: req.user });
});
```

#### 3.3.5 bcryptjs - パスワードハッシュ
**実装原理**：bcryptjsはパスワードハッシュ用のライブラリで、Blowfish暗号化アルゴリズムに基づき、自動ソルト生成と調整可能な作業因子をサポートします。

**設計思想**：
- ランダムソルトを自動生成し、レインボーテーブル攻撃を防止
- 調整可能な作業因子でハッシュ計算の難易度を制御
- 非同期および同期ハッシュ計算をサポート
- 複数のプログラミング言語と互換性あり

**実用例**：
```javascript
const bcrypt = require('bcryptjs');

// パスワードハッシュ化
async function hashPassword(password) {
    const salt = await bcrypt.genSalt(12);
    return await bcrypt.hash(password, salt);
}

// パスワード検証
async function verifyPassword(password, hashedPassword) {
    return await bcrypt.compare(password, hashedPassword);
}

// ユーザー登録例
app.post('/api/register', async (req, res) => {
    try {
        const { username, email, password, name } = req.body;

        // ユーザーの既存確認
        const existingUser = await User.findOne({ $or: [{ username }, { email }] });
        if (existingUser) {
            return res.status(400).json({ message: 'ユーザーは既に存在します' });
        }

        // パスワードハッシュ化
        const passwordHash = await hashPassword(password);

        // 新規ユーザー作成
        const newUser = new User({
            username,
            email,
            passwordHash,
            name
        });

        await newUser.save();

        // トークン生成
        const token = generateToken(newUser);

        res.status(201).json({ message: 'ユーザー登録成功', token });
    } catch (error) {
        res.status(500).json({ message: '登録失敗', error: error.message });
    }
});
```

### 3.4 リアルタイム通信実装

#### 3.4.1 Socket.IO - WebSocket実装
**実装原理**：Socket.IOはWebSocketベースのリアルタイム通信ライブラリで、イベント駆動の双方向通信メカニズムを提供し、ポーリングへのフォールバックをサポートします。

**設計思想**：
- イベント駆動の通信モデル
- ルームと名前空間をサポート
- 自動再接続メカニズム
- バイナリデータ転送をサポート
- クロスブラウザ互換性が良好

**実用例**：
```javascript
const http = require('http');
const socketIO = require('socket.io');

const server = http.createServer(app);
const io = socketIO(server);

// 接続イベントの監視
io.on('connection', (socket) => {
    console.log('新しいクライアントが接続しました:', socket.id);

    // ユーザールームに参加
    socket.join(`user-${req.user.userId}`);

    // カスタムイベントの監視
    socket.on('send-message', (data) => {
        console.log('メッセージ受信:', data);
        // メッセージをブロードキャスト
        socket.broadcast.emit('new-message', data);
    });

    // 切断イベントの監視
    socket.on('disconnect', () => {
        console.log('クライアントが切断しました:', socket.id);
    });
});

// 特定ユーザーにリアルタイム通知を送信
function sendNotificationToUser(userId, notification) {
    io.to(`user-${userId}`).emit('notification', notification);
}

server.listen(3000, () => {
    console.log('WebSocketサポート付きでサーバーがポート3000で起動中');
});
```

