// HTMLエスケープ関数
function escapeHtml(text) {
    if (!text) return '';
    return text
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// ユーザー入力を安全に挿入
function insertUserContent(element, content) {
    element.textContent = content; // 安全、HTMLは実行されない
    // element.innerHTML = content; の使用は避ける // 不安全、XSSの可能性あり
