**實際應用**：
```javascript
const cors = require('cors');

// 基本用法
app.use(cors());

// 配置允許的域名
app.use(cors({
    origin: ['http://localhost:3000', 'https://studyai.example.com'],
    credentials: true
}));
```

#### 3.3.2 Morgan - HTTP 請求日誌記錄
**實現原理**：Morgan 是一個 HTTP 請求日誌中間件，記錄請求的方法、URL、狀態碼、響應時間等信息。

**設計思路**：
- 支持多種日誌格式（combined, common, dev, short, tiny）
- 可自定義日誌格式
- 支持日誌流輸出到文件或其他目的地
- 性能開銷低

**實際應用**：
```javascript
const morgan = require('morgan');

// 開發環境使用 dev 格式
app.use(morgan('dev'));

// 生產環境使用 combined 格式並輸出到文件
const fs = require('fs');
const path = require('path');
const accessLogStream = fs.createWriteStream(
    path.join(__dirname, 'access.log'),
    { flags: 'a' }
);
app.use(morgan('combined', { stream: accessLogStream }));
```

#### 3.3.3 Multer - 文件上傳處理
**實現原理**：Multer 是一個處理 `multipart/form-data` 的中間件，用於處理文件上傳。

**設計思路**：
- 支持內存存儲和磁盤存儲
- 支持文件過濾和限制
- 支持多文件上傳
- 可自定義文件名和存儲路徑

**實際應用**：
```javascript
const multer = require('multer');

// 配置存儲引擎
const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, 'uploads/');
    },
    filename: function (req, file, cb) {
        cb(null, Date.now() + '-' + file.originalname);
    }
});

// 配置文件過濾
const fileFilter = (req, file, cb) => {
    if (file.mimetype.startsWith('image/')) {
        cb(null, true);
    } else {
        cb(new Error('Only images are allowed!'), false);
    }
};

// 創建 multer 實例
const upload = multer({
    storage: storage,
    limits: {
        fileSize: 1024 * 1024 * 5 // 5MB 限制
    },
    fileFilter: fileFilter
});

// 使用 multer 處理單文件上傳
app.post('/api/upload', upload.single('image'), (req, res) => {
    res.json({ message: 'File uploaded successfully', file: req.file });
});
```

#### 3.3.4 jsonwebtoken - JWT 認證機制
**實現原理**：JWT（JSON Web Token）是一種無狀態認證機制，通過加密的 JSON 令牌傳遞用戶身份信息。

**設計思路**：
- 由 Header、Payload 和 Signature 三部分組成
- 使用密鑰進行簽名，確保令牌完整性
- 無狀態設計，減少服務器存儲壓力
- 支持過期時間和刷新機制

**實際應用**：
```javascript
const jwt = require('jsonwebtoken');

// 生成 JWT 令牌
function generateToken(user) {
    return jwt.sign(
        { userId: user._id, username: user.username },
        process.env.JWT_SECRET,
        { expiresIn: '24h' }
    );
}

// 驗證 JWT 令牌的中間件
function verifyToken(req, res, next) {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
        return res.status(401).json({ message: 'No token provided' });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
        if (err) {
            return res.status(401).json({ message: 'Invalid token' });
        }

        req.user = decoded;
        next();
    });
}

// 使用驗證中間件保護路由
app.get('/api/protected', verifyToken, (req, res) => {
    res.json({ message: 'Protected route accessed successfully', user: req.user });
});
```

#### 3.3.5 bcryptjs - 密碼哈希
**實現原理**：bcryptjs 是一個用於密碼哈希的庫，基於 Blowfish 加密算法，支持自動鹽生成和可調的工作因子。

**設計思路**：
- 自動生成隨機鹽，避免彩虹表攻擊
- 可調的工作因子，控制哈希計算難度
- 支持異步和同步哈希計算
- 兼容多個編程語言

**實際應用**：
```javascript
const bcrypt = require('bcryptjs');

// 哈希密碼
async function hashPassword(password) {
    const salt = await bcrypt.genSalt(12);
    return await bcrypt.hash(password, salt);
}

// 驗證密碼
async function verifyPassword(password, hashedPassword) {
    return await bcrypt.compare(password, hashedPassword);
}

// 用戶注冊示例
app.post('/api/register', async (req, res) => {
    try {
        const { username, email, password, name } = req.body;

        // 檢查用戶是否已存在
        const existingUser = await User.findOne({ $or: [{ username }, { email }] });
        if (existingUser) {
            return res.status(400).json({ message: 'User already exists' });
        }

        // 哈希密碼
        const passwordHash = await hashPassword(password);

        // 創建新用戶
        const newUser = new User({
            username,
            email,
            passwordHash,
            name
        });

        await newUser.save();

        // 生成令牌
        const token = generateToken(newUser);

        res.status(201).json({ message: 'User registered successfully', token });
    } catch (error) {
        res.status(500).json({ message: 'Registration failed', error: error.message });
    }
});
```

### 3.4 實時通信實現

#### 3.4.1 Socket.IO - WebSocket 實現
**實現原理**：Socket.IO 是一個基於 WebSocket 的實時通信庫，提供了事件驅動的雙向通信機制，支持降級到輪詢。

**設計思路**：
- 事件驅動的通信模型
- 支持房間和命名空間
- 自動重連機制
- 支持二進制數據傳輸
- 跨瀏覽器兼容性好

**實際應用**：
```javascript
const http = require('http');
const socketIO = require('socket.io');

const server = http.createServer(app);
const io = socketIO(server);

// 監聽連接事件
io.on('connection', (socket) => {
    console.log('New client connected:', socket.id);

    // 加入用戶房間
    socket.join(`user-${req.user.userId}`);

    // 監聽自定義事件
    socket.on('send-message', (data) => {
        console.log('Message received:', data);
        // 廣播消息
        socket.broadcast.emit('new-message', data);
    });

    // 監聽斷開連接事件
    socket.on('disconnect', () => {
        console.log('Client disconnected:', socket.id);
    });
});

// 向特定用戶發送實時通知
function sendNotificationToUser(userId, notification) {
    io.to(`user-${userId}`).emit('notification', notification);
}

server.listen(3000, () => {
    console.log('Server running on port 3000 with WebSocket support');
});
```

